    pub(crate) fn compare_timing_description_event_chain(
        &self,
        other: &Document,
        a: &TimingDescriptionEventChain,
        b: &TimingDescriptionEventChain,
        path: &str,
    ) -> Result<(), String> {
        self.compare_timing_description(other, a.base(), b.base(), path)?;
        if a.get_is_pipelining_permitted() != b.get_is_pipelining_permitted() {
            return Err(format!("{path}: IS_PIPELINING_PERMITTED mismatch"));
        }
        if a.get_response_ref() != b.get_response_ref() {
            return Err(format!("{path}: RESPONSE_REF mismatch"));
        }
        let list_a = a.get_segment_refs();
        let list_b = b.get_segment_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SEGMENT_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.SEGMENT_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.SEGMENT_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.SEGMENT_REFS[{index}]"))?;
        }
        if a.get_stimulus_ref() != b.get_stimulus_ref() {
            return Err(format!("{path}: STIMULUS_REF mismatch"));
        }
        Ok(())
    }
